DASHBOARD_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>Phishing Detection Tool</title>\n    <script src="https://cdn.tailwindcss.com"></script>\n    <style>\n/* Clean, human-made UI stylesheet */\n\n.active-tab {\n    background-color: rgba(30, 41, 59, 0.5);\n    color: #60a5fa;\n    border-bottom: 2px solid #3b82f6;\n}\n\n.example-btn {\n    padding: 0.2rem 0.55rem;\n    border-radius: 0.375rem;\n    background-color: rgba(30, 41, 59, 0.7);\n    border: 1px solid rgba(71, 85, 105, 0.5);\n    font-size: 0.725rem;\n    cursor: pointer;\n    transition: background-color 0.15s ease;\n}\n\n.example-btn:hover {\n    background-color: rgba(51, 65, 85, 0.8);\n}\n\n.badge-danger {\n    background-color: rgba(225, 29, 72, 0.15);\n    border: 1px solid rgba(225, 29, 72, 0.35);\n    color: #fb7185;\n}\n\n.badge-warning {\n    background-color: rgba(217, 119, 6, 0.15);\n    border: 1px solid rgba(217, 119, 6, 0.35);\n    color: #fbbf24;\n}\n\n.badge-safe {\n    background-color: rgba(16, 185, 129, 0.15);\n    border: 1px solid rgba(16, 185, 129, 0.35);\n    color: #34d399;\n}\n\n</style>\n    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">\n    <link rel="preconnect" href="https://fonts.googleapis.com">\n    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">\n</head>\n<body class="bg-slate-900 text-slate-100 min-h-screen flex flex-col font-[\'Inter\',sans-serif]">\n\n    <!-- Navbar -->\n    <header class="border-b border-slate-800 bg-slate-900/90 sticky top-0 z-50">\n        <div class="max-w-6xl mx-auto px-4 h-16 flex items-center justify-between">\n            <div class="flex items-center space-x-3">\n                <div class="w-9 h-9 rounded-lg bg-blue-600 flex items-center justify-center text-white shadow">\n                    <i class="fa-solid fa-shield text-lg"></i>\n                </div>\n                <div>\n                    <span class="font-bold text-base text-white tracking-tight">Phishing Detector</span>\n                    <span class="text-xs text-slate-400 block -mt-0.5">URL & Message Security Scanner</span>\n                </div>\n            </div>\n\n            <div class="flex items-center space-x-3 text-xs text-slate-400">\n                <span class="flex items-center bg-slate-800 border border-slate-700 px-3 py-1.5 rounded-md">\n                    <span class="w-2 h-2 rounded-full bg-emerald-400 mr-2"></span>\n                    Server Online\n                </span>\n            </div>\n        </div>\n    </header>\n\n    <!-- Main Content -->\n    <main class="flex-1 max-w-6xl w-full mx-auto px-4 py-8">\n\n        <!-- Quick Stats Bar -->\n        <div class="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">\n            <div class="bg-slate-800/60 border border-slate-700/60 rounded-xl p-4">\n                <div class="text-xs text-slate-400 font-medium">Total Scanned</div>\n                <div id="stat-total-scans" class="text-2xl font-bold text-white mt-1">0</div>\n            </div>\n            <div class="bg-slate-800/60 border border-slate-700/60 rounded-xl p-4">\n                <div class="text-xs text-slate-400 font-medium">Safe Websites</div>\n                <div id="stat-safe-count" class="text-2xl font-bold text-emerald-400 mt-1">0</div>\n            </div>\n            <div class="bg-slate-800/60 border border-slate-700/60 rounded-xl p-4">\n                <div class="text-xs text-slate-400 font-medium">Suspicious / Phishing</div>\n                <div id="stat-threats-count" class="text-2xl font-bold text-rose-400 mt-1">0</div>\n            </div>\n            <div class="bg-slate-800/60 border border-slate-700/60 rounded-xl p-4">\n                <div class="text-xs text-slate-400 font-medium">Threat Percentage</div>\n                <div id="stat-threat-rate" class="text-2xl font-bold text-amber-400 mt-1">0.0%</div>\n            </div>\n        </div>\n\n        <!-- Navigation Tabs -->\n        <div class="flex border-b border-slate-800 mb-6 space-x-1 sm:space-x-2">\n            <button onclick="switchTab(\'url-tab\')" id="btn-url-tab" class="tab-btn active-tab px-4 py-2.5 rounded-t-lg text-sm font-medium flex items-center space-x-2 border-b-2 border-blue-500 text-blue-400">\n                <i class="fa-solid fa-link text-xs"></i>\n                <span>Scan URL</span>\n            </button>\n            <button onclick="switchTab(\'text-tab\')" id="btn-text-tab" class="tab-btn px-4 py-2.5 rounded-t-lg text-sm font-medium text-slate-400 hover:text-slate-200 flex items-center space-x-2">\n                <i class="fa-solid fa-envelope text-xs"></i>\n                <span>Scan Email / SMS</span>\n            </button>\n            <button onclick="switchTab(\'batch-tab\')" id="btn-batch-tab" class="tab-btn px-4 py-2.5 rounded-t-lg text-sm font-medium text-slate-400 hover:text-slate-200 flex items-center space-x-2">\n                <i class="fa-solid fa-list text-xs"></i>\n                <span>Multiple URLs</span>\n            </button>\n            <button onclick="switchTab(\'history-tab\')" id="btn-history-tab" class="tab-btn px-4 py-2.5 rounded-t-lg text-sm font-medium text-slate-400 hover:text-slate-200 flex items-center space-x-2">\n                <i class="fa-solid fa-clock-rotate-left text-xs"></i>\n                <span>Recent History</span>\n            </button>\n        </div>\n\n        <!-- ============================================================= -->\n        <!-- TAB 1: URL SCANNER -->\n        <!-- ============================================================= -->\n        <div id="url-tab" class="tab-content block space-y-6">\n            \n            <div class="bg-slate-800/40 border border-slate-700/70 rounded-2xl p-6 sm:p-7">\n                <h1 class="text-xl font-bold text-white mb-1">Check a Website Link</h1>\n                <p class="text-sm text-slate-400 mb-5">\n                    Paste any website link below to check if it\'s safe or trying to scam you.\n                </p>\n\n                <form id="url-scan-form" onsubmit="handleUrlScan(event)" class="space-y-4">\n                    <div class="flex flex-col sm:flex-row gap-2">\n                        <div class="relative flex-1">\n                            <input \n                                type="text" \n                                id="target-url" \n                                placeholder="Paste link here (e.g. https://example.com/login)" \n                                required \n                                class="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-3 text-slate-100 placeholder-slate-500 focus:outline-none focus:border-blue-500 text-sm"\n                            >\n                        </div>\n                        <button \n                            type="submit" \n                            id="scan-submit-btn" \n                            class="bg-blue-600 hover:bg-blue-500 text-white font-medium px-6 py-3 rounded-xl text-sm transition flex items-center justify-center space-x-2 shadow"\n                        >\n                            <i class="fa-solid fa-magnifying-glass"></i>\n                            <span>Check Link</span>\n                        </button>\n                    </div>\n\n                    <div class="flex flex-wrap items-center justify-between gap-3 text-xs pt-1 text-slate-400">\n                        <label class="flex items-center space-x-2 cursor-pointer select-none">\n                            <input type="checkbox" id="check-live-threat" checked class="rounded bg-slate-800 border-slate-700 text-blue-600">\n                            <span>Check Google Safe Browsing database</span>\n                        </label>\n\n                        <div class="flex flex-wrap items-center gap-1.5">\n                            <span class="text-slate-500">Try an example:</span>\n                            <button type="button" onclick="fillUrl(\'https://www.google.com\')" class="example-btn">google.com (Safe)</button>\n                            <button type="button" onclick="fillUrl(\'http://paypa1-security.com/login\')" class="example-btn text-rose-300">Fake PayPal</button>\n                            <button type="button" onclick="fillUrl(\'http://192.168.1.100/@login.chase.com\')" class="example-btn text-amber-300">IP & @ Masking</button>\n                            <button type="button" onclick="fillUrl(\'http://random-scam-link-9482.xyz/verify\')" class="example-btn text-rose-300">Suspicious .xyz</button>\n                        </div>\n                    </div>\n                </form>\n            </div>\n\n            <!-- Loading Spinner -->\n            <div id="url-loading" class="hidden text-center py-10 bg-slate-800/30 rounded-xl border border-slate-700">\n                <i class="fa-solid fa-spinner animate-spin text-blue-400 text-3xl mb-3"></i>\n                <div class="text-sm font-medium text-white">Analyzing URL features...</div>\n                <div class="text-xs text-slate-400 mt-0.5">Checking domain name, character patterns, and security lists.</div>\n            </div>\n\n            <!-- Results Card -->\n            <div id="url-results" class="hidden space-y-6">\n                \n                <!-- Main Verdict Banner -->\n                <div id="verdict-banner" class="border rounded-xl p-6 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">\n                    <div class="space-y-1.5">\n                        <div class="flex items-center space-x-2">\n                            <span id="verdict-badge" class="px-3 py-1 rounded-md text-xs font-bold uppercase">\n                                VERDICT\n                            </span>\n                        </div>\n                        <h2 id="verdict-title" class="text-2xl font-bold text-white">MALICIOUS LINK</h2>\n                        <p id="verdict-recommendation" class="text-sm text-slate-300">\n                            Recommendation text here.\n                        </p>\n                    </div>\n\n                    <div class="text-right sm:border-l sm:border-slate-700/60 sm:pl-6">\n                        <div class="text-xs uppercase text-slate-400 font-medium">Risk Score</div>\n                        <div class="text-3xl font-extrabold" id="risk-score-value">85%</div>\n                        <div id="prob-subtext" class="text-xs text-slate-400 mt-0.5">Moderate to high threat</div>\n                    </div>\n                </div>\n\n                <!-- 4 Simple Check Cards -->\n                <div class="grid grid-cols-2 md:grid-cols-4 gap-3">\n                    <div class="bg-slate-800/50 border border-slate-700/70 rounded-xl p-3.5">\n                        <div class="text-xs text-slate-400">Brand Impersonation</div>\n                        <div id="stat-brand" class="text-sm font-semibold text-white mt-1">None</div>\n                    </div>\n\n                    <div class="bg-slate-800/50 border border-slate-700/70 rounded-xl p-3.5">\n                        <div class="text-xs text-slate-400">Google Safe Browsing</div>\n                        <div id="stat-google" class="text-sm font-semibold text-white mt-1">Clean</div>\n                    </div>\n\n                    <div class="bg-slate-800/50 border border-slate-700/70 rounded-xl p-3.5">\n                        <div class="text-xs text-slate-400">Domain Entropy</div>\n                        <div id="stat-entropy" class="text-sm font-semibold text-white mt-1">Normal</div>\n                    </div>\n\n                    <div class="bg-slate-800/50 border border-slate-700/70 rounded-xl p-3.5">\n                        <div class="text-xs text-slate-400">DNS Status</div>\n                        <div id="stat-dns" class="text-sm font-semibold text-white mt-1">Active</div>\n                    </div>\n                </div>\n\n                <!-- Why was this flagged? (Human friendly explanation) -->\n                <div class="bg-slate-800/50 border border-slate-700/70 rounded-xl p-5">\n                    <h3 class="text-sm font-semibold text-white mb-3 flex items-center space-x-2">\n                        <i class="fa-solid fa-circle-info text-blue-400"></i>\n                        <span>Why was this score given?</span>\n                    </h3>\n                    <div id="contributions-list" class="space-y-2.5">\n                    </div>\n                </div>\n\n                <!-- Extracted Details Table -->\n                <div class="bg-slate-800/50 border border-slate-700/70 rounded-xl p-5">\n                    <h3 class="text-sm font-semibold text-white mb-3 flex items-center space-x-2">\n                        <i class="fa-solid fa-list-check text-slate-400"></i>\n                        <span>URL Breakdown & Characteristics</span>\n                    </h3>\n                    <div class="overflow-x-auto">\n                        <table class="w-full text-left text-xs">\n                            <thead>\n                                <tr class="border-b border-slate-700 text-slate-400">\n                                    <th class="py-2 px-3">Check</th>\n                                    <th class="py-2 px-3">Value</th>\n                                    <th class="py-2 px-3">What it means</th>\n                                </tr>\n                            </thead>\n                            <tbody id="raw-features-table" class="divide-y divide-slate-800 text-slate-300">\n                            </tbody>\n                        </table>\n                    </div>\n                </div>\n\n            </div>\n        </div>\n\n        <!-- ============================================================= -->\n        <!-- TAB 2: EMAIL & SMS PHISHING -->\n        <!-- ============================================================= -->\n        <div id="text-tab" class="tab-content hidden space-y-6">\n            <div class="bg-slate-800/40 border border-slate-700/70 rounded-2xl p-6 sm:p-7">\n                <h2 class="text-xl font-bold text-white mb-1">Check Suspicious Message or Email</h2>\n                <p class="text-sm text-slate-400 mb-5">\n                    Paste the text of an email or SMS you received to check for fake urgency or scam patterns.\n                </p>\n\n                <form id="text-scan-form" onsubmit="handleTextScan(event)" class="space-y-4">\n                    <textarea \n                        id="phish-text" \n                        rows="5" \n                        placeholder="Paste email or SMS text here..." \n                        required\n                        class="w-full bg-slate-900 border border-slate-700 rounded-xl p-4 text-slate-100 placeholder-slate-500 focus:outline-none focus:border-blue-500 text-sm"\n                    ></textarea>\n\n                    <div class="flex flex-wrap items-center justify-between gap-3 text-xs">\n                        <div class="flex flex-wrap items-center gap-1.5 text-slate-400">\n                            <span class="text-slate-500">Examples:</span>\n                            <button type="button" onclick="fillTextSample(\'bank\')" class="example-btn text-rose-300">Bank Alert Scam</button>\n                            <button type="button" onclick="fillTextSample(\'lottery\')" class="example-btn text-amber-300">Prize Winner Scam</button>\n                            <button type="button" onclick="fillTextSample(\'normal\')" class="example-btn text-emerald-300">Normal Meeting Email</button>\n                        </div>\n\n                        <button \n                            type="submit" \n                            class="bg-blue-600 hover:bg-blue-500 text-white font-medium px-5 py-2.5 rounded-xl text-sm transition shadow"\n                        >\n                            Analyze Message\n                        </button>\n                    </div>\n                </form>\n            </div>\n\n            <!-- Text Results Card -->\n            <div id="text-results" class="hidden space-y-4">\n                <div id="text-verdict-banner" class="border rounded-xl p-5 flex items-center justify-between">\n                    <div>\n                        <span id="text-verdict-badge" class="px-2.5 py-0.5 rounded text-xs font-bold uppercase">VERDICT</span>\n                        <h3 id="text-verdict-title" class="text-xl font-bold text-white mt-1">High Risk</h3>\n                    </div>\n                    <div class="text-right">\n                        <div class="text-xs uppercase text-slate-400 font-medium">Scam Probability</div>\n                        <div class="text-2xl font-bold text-white" id="text-risk-score">75%</div>\n                    </div>\n                </div>\n\n                <div class="grid grid-cols-1 md:grid-cols-2 gap-4">\n                    <div class="bg-slate-800/50 border border-slate-700/70 rounded-xl p-4">\n                        <h4 class="text-xs font-bold uppercase tracking-wider text-amber-400 mb-2">Urgent or Pressure Phrases Found</h4>\n                        <ul id="urgency-phrases-list" class="space-y-1.5 text-xs text-slate-300">\n                        </ul>\n                    </div>\n\n                    <div class="bg-slate-800/50 border border-slate-700/70 rounded-xl p-4">\n                        <h4 class="text-xs font-bold uppercase tracking-wider text-blue-400 mb-2">Web Links Found in Message</h4>\n                        <ul id="extracted-urls-list" class="space-y-1.5 text-xs font-mono text-slate-300">\n                        </ul>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <!-- ============================================================= -->\n        <!-- TAB 3: BATCH SCANNER -->\n        <!-- ============================================================= -->\n        <div id="batch-tab" class="tab-content hidden space-y-6">\n            <div class="bg-slate-800/40 border border-slate-700/70 rounded-2xl p-6 sm:p-7">\n                <h2 class="text-xl font-bold text-white mb-1">Check Multiple URLs at Once</h2>\n                <p class="text-sm text-slate-400 mb-5">\n                    Paste several links below (one per line) to scan all of them together.\n                </p>\n\n                <form id="batch-scan-form" onsubmit="handleBatchScan(event)" class="space-y-4">\n                    <textarea \n                        id="batch-urls" \n                        rows="5" \n                        placeholder="https://google.com&#10;http://paypa1-security.com&#10;https://example.com" \n                        required\n                        class="w-full bg-slate-900 border border-slate-700 rounded-xl p-4 text-slate-100 placeholder-slate-500 focus:outline-none focus:border-blue-500 text-sm font-mono"\n                    ></textarea>\n\n                    <div class="flex items-center justify-between">\n                        <button type="button" onclick="fillBatchSample()" class="example-btn">Load Sample Links</button>\n                        <button \n                            type="submit" \n                            class="bg-blue-600 hover:bg-blue-500 text-white font-medium px-5 py-2.5 rounded-xl text-sm transition shadow"\n                        >\n                            Scan All Links\n                        </button>\n                    </div>\n                </form>\n            </div>\n\n            <div id="batch-results" class="hidden bg-slate-800/50 border border-slate-700/70 rounded-xl p-5">\n                <h3 class="text-sm font-semibold text-white mb-3">Batch Results</h3>\n                <div class="overflow-x-auto">\n                    <table class="w-full text-left text-xs">\n                        <thead>\n                            <tr class="border-b border-slate-700 text-slate-400">\n                                <th class="py-2 px-3">URL</th>\n                                <th class="py-2 px-3">Risk Score</th>\n                                <th class="py-2 px-3">Status</th>\n                                <th class="py-2 px-3 text-right">Action</th>\n                            </tr>\n                        </thead>\n                        <tbody id="batch-table-body" class="divide-y divide-slate-800 text-slate-300">\n                        </tbody>\n                    </table>\n                </div>\n            </div>\n        </div>\n\n        <!-- ============================================================= -->\n        <!-- TAB 4: RECENT HISTORY -->\n        <!-- ============================================================= -->\n        <div id="history-tab" class="tab-content hidden space-y-6">\n            <div class="bg-slate-800/40 border border-slate-700/70 rounded-2xl p-6 sm:p-7">\n                <div class="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 mb-5">\n                    <div>\n                        <h2 class="text-xl font-bold text-white">Past Scans History</h2>\n                        <p class="text-xs text-slate-400 mt-0.5">All scans are saved locally in the SQLite database.</p>\n                    </div>\n\n                    <div class="flex items-center space-x-2">\n                        <button onclick="exportCsv()" class="px-3.5 py-2 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 text-xs font-medium border border-slate-700 transition flex items-center space-x-1.5">\n                            <i class="fa-solid fa-download text-xs text-slate-400"></i>\n                            <span>Export CSV</span>\n                        </button>\n                        <button onclick="clearHistory()" class="px-3.5 py-2 rounded-lg bg-rose-950/40 hover:bg-rose-900/60 text-rose-300 text-xs font-medium border border-rose-800/40 transition flex items-center space-x-1.5">\n                            <i class="fa-solid fa-trash-can text-xs"></i>\n                            <span>Clear</span>\n                        </button>\n                    </div>\n                </div>\n\n                <div class="overflow-x-auto">\n                    <table class="w-full text-left text-xs">\n                        <thead>\n                            <tr class="border-b border-slate-700 text-slate-400 bg-slate-900/50">\n                                <th class="py-2.5 px-3">ID</th>\n                                <th class="py-2.5 px-3">Time</th>\n                                <th class="py-2.5 px-3">URL</th>\n                                <th class="py-2.5 px-3">Risk</th>\n                                <th class="py-2.5 px-3">Status</th>\n                                <th class="py-2.5 px-3 text-right">Action</th>\n                            </tr>\n                        </thead>\n                        <tbody id="history-table-body" class="divide-y divide-slate-800 text-slate-300">\n                        </tbody>\n                    </table>\n                </div>\n            </div>\n        </div>\n\n    </main>\n\n    <!-- Footer -->\n    <footer class="border-t border-slate-800 py-6 text-center text-xs text-slate-500">\n        <p>Phishing Detection Tool — Built with Python, FastAPI, and SQLite</p>\n    </footer>\n\n    <script>\n// Phishing Detector - Frontend Logic\n\ndocument.addEventListener(\'DOMContentLoaded\', () => {\n    fetchAnalytics();\n    fetchHistory();\n});\n\n// Update top statistics\nasync function fetchAnalytics() {\n    try {\n        const res = await fetch(\'/api/analytics\');\n        if (!res.ok) return;\n        const data = await res.json();\n        const a = data.analytics;\n\n        document.getElementById(\'stat-total-scans\').innerText = a.total_scans;\n        document.getElementById(\'stat-safe-count\').innerText = a.safe_count;\n        document.getElementById(\'stat-threats-count\').innerText = a.phishing_count + a.suspicious_count;\n        document.getElementById(\'stat-threat-rate\').innerText = `${a.threat_rate}%`;\n    } catch (e) {\n        console.error("Failed to load statistics:", e);\n    }\n}\n\n// Fetch scan history from SQLite\nasync function fetchHistory() {\n    try {\n        const res = await fetch(\'/api/history?limit=20\');\n        if (!res.ok) return;\n        const data = await res.json();\n        const tbody = document.getElementById(\'history-table-body\');\n        if (!tbody) return;\n\n        tbody.innerHTML = \'\';\n        if (data.scans.length === 0) {\n            tbody.innerHTML = \'<tr><td colspan="6" class="py-6 text-center text-slate-500 text-xs">No scans recorded yet. Enter a link above to get started.</td></tr>\';\n            return;\n        }\n\n        data.scans.forEach(s => {\n            const tr = document.createElement(\'tr\');\n            tr.className = "hover:bg-slate-800/30 transition";\n\n            let badgeClass = "badge-safe";\n            if (s.verdict_level === \'danger\') badgeClass = "badge-danger";\n            else if (s.verdict_level === \'warning\') badgeClass = "badge-warning";\n\n            tr.innerHTML = `\n                <td class="py-2.5 px-3 text-slate-500 font-mono">#${s.id}</td>\n                <td class="py-2.5 px-3 text-slate-400 text-[11px]">${s.timestamp}</td>\n                <td class="py-2.5 px-3 truncate max-w-xs text-slate-200" title="${s.url}">${s.url}</td>\n                <td class="py-2.5 px-3 font-semibold ${s.verdict_level === \'danger\' ? \'text-rose-400\' : (s.verdict_level === \'warning\' ? \'text-amber-400\' : \'text-emerald-400\')}">${s.risk_score}%</td>\n                <td class="py-2.5 px-3"><span class="px-2 py-0.5 rounded text-xs font-medium ${badgeClass}">${s.verdict}</span></td>\n                <td class="py-2.5 px-3 text-right">\n                    <button type="button" onclick="inspectExtractedUrl(\'${s.url}\')" class="text-xs px-2.5 py-1 rounded bg-slate-800 text-slate-300 hover:bg-slate-700">Check Again</button>\n                </td>\n            `;\n            tbody.appendChild(tr);\n        });\n    } catch (e) {\n        console.error("Failed to load history:", e);\n    }\n}\n\nasync function clearHistory() {\n    if (!confirm("Clear all scan history?")) return;\n    try {\n        await fetch(\'/api/clear-history\', { method: \'POST\' });\n        fetchAnalytics();\n        fetchHistory();\n    } catch (e) {\n        alert("Error: " + e.message);\n    }\n}\n\nfunction exportCsv() {\n    window.location.href = \'/api/export-csv\';\n}\n\n// Tab Switching\nfunction switchTab(tabId) {\n    document.querySelectorAll(\'.tab-content\').forEach(tab => {\n        tab.classList.add(\'hidden\');\n        tab.classList.remove(\'block\');\n    });\n\n    document.querySelectorAll(\'.tab-btn\').forEach(btn => {\n        btn.classList.remove(\'active-tab\', \'border-b-2\', \'border-blue-500\', \'text-blue-400\');\n        btn.classList.add(\'text-slate-400\');\n    });\n\n    const activeTab = document.getElementById(tabId);\n    if (activeTab) {\n        activeTab.classList.remove(\'hidden\');\n        activeTab.classList.add(\'block\');\n    }\n\n    const activeBtn = document.getElementById(`btn-${tabId}`);\n    if (activeBtn) {\n        activeBtn.classList.add(\'active-tab\', \'border-b-2\', \'border-blue-500\', \'text-blue-400\');\n        activeBtn.classList.remove(\'text-slate-400\');\n    }\n\n    if (tabId === \'history-tab\') {\n        fetchHistory();\n    }\n}\n\n// Preset Helpers\nfunction fillUrl(url) {\n    document.getElementById(\'target-url\').value = url;\n    document.getElementById(\'url-scan-form\').dispatchEvent(new Event(\'submit\'));\n}\n\nfunction fillTextSample(type) {\n    const textarea = document.getElementById(\'phish-text\');\n    if (type === \'bank\') {\n        textarea.value = "URGENT: Your bank account has been locked due to suspicious activity. Please verify your login immediately within 24 hours at http://paypa1-security.com/login to prevent account suspension.";\n    } else if (type === \'lottery\') {\n        textarea.value = "Congratulations! You have been selected to receive a $5,000 cash prize. Click here to claim your reward: http://free-bonus-claim.xyz/verify";\n    } else {\n        textarea.value = "Hi team, reminder that our project progress meeting is tomorrow at 10 AM in Conference Room B. See you there!";\n    }\n    document.getElementById(\'text-scan-form\').dispatchEvent(new Event(\'submit\'));\n}\n\nfunction fillBatchSample() {\n    const textarea = document.getElementById(\'batch-urls\');\n    textarea.value = [\n        "https://www.google.com",\n        "https://www.github.com",\n        "http://paypa1-security.com/login",\n        "http://192.168.1.100/@login.bank.com",\n        "https://amazon.com",\n        "http://cheap-update-account.xyz/verify"\n    ].join("\\n");\n}\n\n// URL Scan Form\nasync function handleUrlScan(event) {\n    event.preventDefault();\n    const urlInput = document.getElementById(\'target-url\').value.trim();\n    if (!urlInput) return;\n\n    const checkLive = document.getElementById(\'check-live-threat\').checked;\n    const loadingElem = document.getElementById(\'url-loading\');\n    const resultsElem = document.getElementById(\'url-results\');\n    const submitBtn = document.getElementById(\'scan-submit-btn\');\n\n    loadingElem.classList.remove(\'hidden\');\n    resultsElem.classList.add(\'hidden\');\n    submitBtn.disabled = true;\n\n    try {\n        const response = await fetch(\'/api/scan\', {\n            method: \'POST\',\n            headers: { \'Content-Type\': \'application/json\' },\n            body: JSON.stringify({ url: urlInput, check_live_threat: checkLive })\n        });\n\n        if (!response.ok) {\n            throw new Error(`Server returned error ${response.status}`);\n        }\n\n        const data = await response.json();\n        renderUrlResults(data);\n\n        fetchAnalytics();\n        fetchHistory();\n    } catch (err) {\n        alert("Scan Error: " + err.message);\n    } finally {\n        loadingElem.classList.add(\'hidden\');\n        submitBtn.disabled = false;\n    }\n}\n\nfunction renderUrlResults(data) {\n    const analysis = data.analysis;\n    const dns = data.dns;\n    const threatIntel = data.threat_intel;\n    const feats = analysis.features;\n\n    const resultsElem = document.getElementById(\'url-results\');\n    resultsElem.classList.remove(\'hidden\');\n\n    const banner = document.getElementById(\'verdict-banner\');\n    const badge = document.getElementById(\'verdict-badge\');\n    const title = document.getElementById(\'verdict-title\');\n    const recommendation = document.getElementById(\'verdict-recommendation\');\n    const scoreVal = document.getElementById(\'risk-score-value\');\n    const probSubtext = document.getElementById(\'prob-subtext\');\n\n    scoreVal.innerText = `${analysis.risk_score}%`;\n    title.innerText = analysis.verdict;\n    recommendation.innerText = analysis.recommendation;\n\n    banner.className = "border rounded-xl p-6 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 ";\n    badge.className = "px-3 py-1 rounded-md text-xs font-bold uppercase ";\n\n    if (analysis.verdict_level === \'danger\') {\n        banner.classList.add("bg-rose-950/20", "border-rose-900/50");\n        badge.classList.add("badge-danger");\n        scoreVal.className = "text-3xl font-extrabold text-rose-400";\n        probSubtext.innerText = "High risk of phishing / fraud";\n    } else if (analysis.verdict_level === \'warning\') {\n        banner.classList.add("bg-amber-950/20", "border-amber-900/50");\n        badge.classList.add("badge-warning");\n        scoreVal.className = "text-3xl font-extrabold text-amber-400";\n        probSubtext.innerText = "Multiple suspicious patterns detected";\n    } else {\n        banner.classList.add("bg-emerald-950/20", "border-emerald-900/50");\n        badge.classList.add("badge-safe");\n        scoreVal.className = "text-3xl font-extrabold text-emerald-400";\n        probSubtext.innerText = "Link looks normal and safe";\n    }\n    badge.innerText = analysis.verdict_level === \'danger\' ? \'Phishing Risk\' : (analysis.verdict_level === \'warning\' ? \'Suspicious\' : \'Safe\');\n\n    // Simple 4 indicators\n    const brandElem = document.getElementById(\'stat-brand\');\n    if (feats.typosquat_flag) {\n        brandElem.innerText = feats.brand_spoofed || "Yes (Fake Brand)";\n        brandElem.className = "text-sm font-semibold text-rose-400 mt-1";\n    } else {\n        brandElem.innerText = "Clean";\n        brandElem.className = "text-sm font-semibold text-emerald-400 mt-1";\n    }\n\n    const googleElem = document.getElementById(\'stat-google\');\n    if (threatIntel.flagged) {\n        googleElem.innerText = "Threat Found";\n        googleElem.className = "text-sm font-semibold text-rose-400 mt-1";\n    } else {\n        googleElem.innerText = "Clean";\n        googleElem.className = "text-sm font-semibold text-emerald-400 mt-1";\n    }\n\n    const entropyElem = document.getElementById(\'stat-entropy\');\n    if (feats.domain_entropy > 3.6) {\n        entropyElem.innerText = "High (Random text)";\n        entropyElem.className = "text-sm font-semibold text-rose-400 mt-1";\n    } else {\n        entropyElem.innerText = "Normal";\n        entropyElem.className = "text-sm font-semibold text-emerald-400 mt-1";\n    }\n\n    const dnsElem = document.getElementById(\'stat-dns\');\n    if (dns.resolves) {\n        dnsElem.innerText = "Valid Domain";\n        dnsElem.className = "text-sm font-semibold text-emerald-400 mt-1";\n    } else {\n        dnsElem.innerText = "Unresolved";\n        dnsElem.className = "text-sm font-semibold text-amber-400 mt-1";\n    }\n\n    // Reasons list\n    const contributionsList = document.getElementById(\'contributions-list\');\n    contributionsList.innerHTML = \'\';\n\n    analysis.contributions.forEach(item => {\n        const div = document.createElement(\'div\');\n        const isSafe = item.impact.includes("Safe");\n        div.className = `p-3 rounded-lg border text-xs flex items-start space-x-2.5 ${isSafe ? \'bg-slate-900/40 border-slate-700/60 text-slate-300\' : \'bg-slate-900 border-slate-700/80 text-slate-200\'}`;\n        \n        div.innerHTML = `\n            <i class="fa-solid ${isSafe ? \'fa-check text-emerald-400\' : \'fa-triangle-exclamation text-amber-400\'} mt-0.5"></i>\n            <div>\n                <span class="font-semibold text-white">${item.feature}:</span>\n                <span class="text-slate-300 ml-1">${item.description}</span>\n            </div>\n        `;\n        contributionsList.appendChild(div);\n    });\n\n    // Details table\n    const tableBody = document.getElementById(\'raw-features-table\');\n    tableBody.innerHTML = \'\';\n\n    const featureDefinitions = [\n        { key: "has_ip", label: "IP Address in Domain", desc: "Using an IP address like 192.168.1.1 instead of a real website name" },\n        { key: "count_at", label: "\'@\' Symbol", desc: "The @ symbol can confuse web browsers and redirect you elsewhere" },\n        { key: "typosquat_flag", label: "Brand Lookalike", desc: "Checks if link mimics brands like PayPal, Google, or Apple" },\n        { key: "domain_entropy", label: "Character Randomness", desc: "High randomness indicates auto-generated temporary scam links" },\n        { key: "subdomains_count", label: "Subdomain Count", desc: "Multiple subdomains are often used to hide the real destination" },\n        { key: "count_hyphens", label: "Hyphen Count (-)", desc: "Scammers frequently use hyphens like \'paypal-security-update\'" },\n        { key: "is_suspicious_tld", label: "Cheap / Risky Extension", desc: "Extensions like .xyz, .top, or .icu with high spam rates" },\n        { key: "keyword_count", label: "Login / Account Keywords", desc: "Checks for words like login, verify, banking, update, or account" },\n        { key: "url_length", label: "URL Length", desc: "Very long URLs designed to hide real addresses on mobile screens" }\n    ];\n\n    featureDefinitions.forEach(item => {\n        const val = feats[item.key] !== undefined ? feats[item.key] : "-";\n        const tr = document.createElement(\'tr\');\n        tr.className = "hover:bg-slate-800/30 transition";\n        tr.innerHTML = `\n            <td class="py-2 px-3 font-medium text-slate-200">${item.label}</td>\n            <td class="py-2 px-3 font-mono font-semibold text-blue-400">${val}</td>\n            <td class="py-2 px-3 text-slate-400">${item.desc}</td>\n        `;\n        tableBody.appendChild(tr);\n    });\n\n    resultsElem.scrollIntoView({ behavior: \'smooth\', block: \'nearest\' });\n}\n\n// Message Scan\nasync function handleTextScan(event) {\n    event.preventDefault();\n    const text = document.getElementById(\'phish-text\').value.trim();\n    if (!text) return;\n\n    try {\n        const response = await fetch(\'/api/scan-text\', {\n            method: \'POST\',\n            headers: { \'Content-Type\': \'application/json\' },\n            body: JSON.stringify({ text: text })\n        });\n\n        const data = await response.json();\n        const analysis = data.analysis;\n\n        const results = document.getElementById(\'text-results\');\n        results.classList.remove(\'hidden\');\n\n        const banner = document.getElementById(\'text-verdict-banner\');\n        const badge = document.getElementById(\'text-verdict-badge\');\n        const title = document.getElementById(\'text-verdict-title\');\n        const score = document.getElementById(\'text-risk-score\');\n\n        score.innerText = `${analysis.risk_score}%`;\n        title.innerText = analysis.verdict;\n\n        banner.className = "border rounded-xl p-5 flex items-center justify-between ";\n        badge.className = "px-2.5 py-0.5 rounded text-xs font-bold uppercase ";\n\n        if (analysis.verdict_level === \'danger\') {\n            banner.classList.add("bg-rose-950/20", "border-rose-900/50");\n            badge.classList.add("badge-danger");\n        } else if (analysis.verdict_level === \'warning\') {\n            banner.classList.add("bg-amber-950/20", "border-amber-900/50");\n            badge.classList.add("badge-warning");\n        } else {\n            banner.classList.add("bg-emerald-950/20", "border-emerald-900/50");\n            badge.classList.add("badge-safe");\n        }\n\n        const urgencyList = document.getElementById(\'urgency-phrases-list\');\n        urgencyList.innerHTML = \'\';\n        if (analysis.matched_urgency_phrases.length === 0) {\n            urgencyList.innerHTML = \'<li class="text-slate-500 italic">No suspicious urgency words found.</li>\';\n        } else {\n            analysis.matched_urgency_phrases.forEach(phrase => {\n                const li = document.createElement(\'li\');\n                li.className = "text-rose-300 font-medium";\n                li.innerHTML = `<i class="fa-solid fa-triangle-exclamation text-rose-400 mr-1.5"></i>"${phrase}"`;\n                urgencyList.appendChild(li);\n            });\n        }\n\n        const urlList = document.getElementById(\'extracted-urls-list\');\n        urlList.innerHTML = \'\';\n        if (analysis.embedded_urls.length === 0) {\n            urlList.innerHTML = \'<li class="text-slate-500 italic">No links found in message.</li>\';\n        } else {\n            analysis.embedded_urls.forEach(u => {\n                const li = document.createElement(\'li\');\n                li.className = "flex items-center justify-between bg-slate-900 p-2 rounded border border-slate-700/60";\n                li.innerHTML = `\n                    <span class="truncate max-w-xs text-blue-300">${u}</span>\n                    <button type="button" onclick="inspectExtractedUrl(\'${u}\')" class="text-xs px-2 py-1 rounded bg-slate-800 text-blue-400 hover:bg-slate-700">Check Link</button>\n                `;\n                urlList.appendChild(li);\n            });\n        }\n\n        results.scrollIntoView({ behavior: \'smooth\', block: \'nearest\' });\n    } catch (err) {\n        alert("Error: " + err.message);\n    }\n}\n\nfunction inspectExtractedUrl(url) {\n    switchTab(\'url-tab\');\n    document.getElementById(\'target-url\').value = url;\n    document.getElementById(\'url-scan-form\').dispatchEvent(new Event(\'submit\'));\n}\n\n// Batch Scan\nasync function handleBatchScan(event) {\n    event.preventDefault();\n    const raw = document.getElementById(\'batch-urls\').value;\n    const lines = raw.split(\'\\n\').map(l => l.trim()).filter(l => l.length > 0);\n    if (lines.length === 0) return;\n\n    try {\n        const response = await fetch(\'/api/batch-scan\', {\n            method: \'POST\',\n            headers: { \'Content-Type\': \'application/json\' },\n            body: JSON.stringify({ urls: lines })\n        });\n\n        const data = await response.json();\n        const resultsBox = document.getElementById(\'batch-results\');\n        const tbody = document.getElementById(\'batch-table-body\');\n        tbody.innerHTML = \'\';\n        resultsBox.classList.remove(\'hidden\');\n\n        data.results.forEach(res => {\n            const tr = document.createElement(\'tr\');\n            tr.className = "hover:bg-slate-800/30 transition";\n            \n            let badgeClass = "badge-safe";\n            if (res.verdict_level === \'danger\') badgeClass = "badge-danger";\n            else if (res.verdict_level === \'warning\') badgeClass = "badge-warning";\n\n            tr.innerHTML = `\n                <td class="py-2 px-3 truncate max-w-sm text-slate-200">${res.url}</td>\n                <td class="py-2 px-3 font-semibold ${res.verdict_level === \'danger\' ? \'text-rose-400\' : (res.verdict_level === \'warning\' ? \'text-amber-400\' : \'text-emerald-400\')}">${res.risk_score}%</td>\n                <td class="py-2 px-3"><span class="px-2 py-0.5 rounded text-xs font-medium ${badgeClass}">${res.verdict}</span></td>\n                <td class="py-2 px-3 text-right">\n                    <button type="button" onclick="inspectExtractedUrl(\'${res.url}\')" class="text-xs px-2 py-1 rounded bg-slate-800 text-blue-400 hover:bg-slate-700">Check</button>\n                </td>\n            `;\n            tbody.appendChild(tr);\n        });\n\n        resultsBox.scrollIntoView({ behavior: \'smooth\', block: \'nearest\' });\n        fetchAnalytics();\n        fetchHistory();\n    } catch (err) {\n        alert("Batch scan error: " + err.message);\n    }\n}\n\n</script>\n</body>\n</html>\n'
